// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {
  AccessControlDefaultAdminRules
} from "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import {ExchangeRate, ISwapOracle, RouteAsset} from "./interfaces/ISwapOracle.sol";
import {MinimalEIP712} from "./utils/MinimalEIP712.sol";

struct SignedOracleQuote {
  uint64 expiresAt;
  ExchangeRate[] rates;
  bytes signature;
}

/// @title SignedSwapOracle
/// @author Agustin Aguilar
/// @notice Decodes and verifies signed offchain route-rate payloads
contract SignedSwapOracle is ISwapOracle, AccessControlDefaultAdminRules, MinimalEIP712 {
  bytes32 public constant SIGNER_ROLE = keccak256("SIGNER_ROLE");

  /// @notice Maximum distance between `block.timestamp` and a quote's `expiresAt`
  /// @dev Bounds how long a quote remains valid, not its age: the quote has no issue time, so one signed with a longer
  /// expiry is accepted during its last `MAX_QUOTE_TTL`. Signers MUST NOT sign an `expiresAt` more than `MAX_QUOTE_TTL`
  /// after signing time; the oracle service issues 5 minute quotes
  uint256 public constant MAX_QUOTE_TTL = 1 hours;

  bytes32 private constant ORACLE_QUOTE_TYPEHASH = keccak256(
    "SignedOracleQuote(address route,bytes32 assetsHash,uint256 outputAsset,bytes32 inputAssetsHash,uint64 expiresAt,bytes32 ratesHash)"
  );

  error ZeroAddress();
  error ExpiredOracleQuote(uint256 _expiresAt, uint256 _timestamp);
  error OracleQuoteTtlTooLong(uint256 _expiresAt, uint256 _maxExpiresAt);

  constructor(address _initialAdmin, address[] memory _initialSigners)
    AccessControlDefaultAdminRules(0, _initialAdmin)
    MinimalEIP712("TrailsPdasSwapOracle", "1")
  {
    uint256 numSigners = _initialSigners.length;
    for (uint256 i = 0; i < numSigners; i++) {
      if (_initialSigners[i] == address(0)) {
        revert ZeroAddress();
      }

      _grantRole(SIGNER_ROLE, _initialSigners[i]);
    }
  }

  /// @notice Returns rates in the requested input-asset order after verifying the signed payload
  function rates(
    address _route,
    RouteAsset[] calldata _assets,
    uint256 _outputAsset,
    uint256[] calldata _inputAssets,
    bytes calldata _payload
  ) external view returns (ExchangeRate[] memory _rates) {
    SignedOracleQuote memory quote = abi.decode(_payload, (SignedOracleQuote));
    _verifyQuote(_route, _assets, _outputAsset, _inputAssets, quote);

    return quote.rates;
  }

  /// @notice Returns the EIP-712 digest signed by the oracle signer
  function quoteDigest(
    address _route,
    RouteAsset[] calldata _assets,
    uint256 _outputAsset,
    uint256[] calldata _inputAssets,
    SignedOracleQuote calldata _quote
  ) external view returns (bytes32) {
    return _quoteDigest(_route, _assets, _outputAsset, _inputAssets, _quote);
  }

  function _verifyQuote(
    address _route,
    RouteAsset[] calldata _assets,
    uint256 _outputAsset,
    uint256[] calldata _inputAssets,
    SignedOracleQuote memory _quote
  ) private view {
    if (_quote.expiresAt < block.timestamp) {
      revert ExpiredOracleQuote(_quote.expiresAt, block.timestamp);
    }
    if (_quote.expiresAt > block.timestamp + MAX_QUOTE_TTL) {
      revert OracleQuoteTtlTooLong(_quote.expiresAt, block.timestamp + MAX_QUOTE_TTL);
    }

    address recovered =
      ECDSA.recover(_quoteDigest(_route, _assets, _outputAsset, _inputAssets, _quote), _quote.signature);
    _checkRole(SIGNER_ROLE, recovered);
  }

  function _quoteDigest(
    address _route,
    RouteAsset[] calldata _assets,
    uint256 _outputAsset,
    uint256[] calldata _inputAssets,
    SignedOracleQuote memory _quote
  ) private view returns (bytes32) {
    return _hashTypedDataV4(
      keccak256(
        abi.encode(
          ORACLE_QUOTE_TYPEHASH,
          _route,
          keccak256(abi.encode(_assets)),
          _outputAsset,
          keccak256(abi.encode(_inputAssets)),
          _quote.expiresAt,
          keccak256(abi.encode(_quote.rates))
        )
      )
    );
  }
}

