// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

struct RouteAsset {
  uint256 chainId;
  address token;
}

struct ExchangeRate {
  uint256 numerator;
  uint256 denominator;
}

/// @title ISwapOracle
/// @author Agustin Aguilar
/// @notice Returns route-level exchange rates from an oracle-specific payload
interface ISwapOracle {
  /// @notice Returns rates for `_inputAssets` valued against `_outputAsset`, in the same order
  function rates(
    address _route,
    RouteAsset[] calldata _assets,
    uint256 _outputAsset,
    uint256[] calldata _inputAssets,
    bytes calldata _payload
  ) external view returns (ExchangeRate[] memory _rates);
}

