// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC5267} from "@openzeppelin/contracts/interfaces/IERC5267.sol";

/// @notice EIP-712 domain hashing without OpenZeppelin string utilities that require Cancun opcodes.
abstract contract MinimalEIP712 is IERC5267 {
  bytes32 private constant TYPE_HASH =
    keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

  bytes32 private immutable CACHED_DOMAIN_SEPARATOR;
  uint256 private immutable CACHED_CHAIN_ID;
  address private immutable CACHED_THIS;
  bytes32 private immutable HASHED_NAME;
  bytes32 private immutable HASHED_VERSION;

  string private name;
  string private version;

  constructor(string memory _name, string memory _version) {
    name = _name;
    version = _version;
    HASHED_NAME = keccak256(bytes(_name));
    HASHED_VERSION = keccak256(bytes(_version));
    CACHED_CHAIN_ID = block.chainid;
    CACHED_DOMAIN_SEPARATOR = _buildDomainSeparator();
    CACHED_THIS = address(this);
  }

  function eip712Domain()
    public
    view
    virtual
    returns (
      bytes1 fields,
      string memory domainName,
      string memory domainVersion,
      uint256 chainId,
      address verifyingContract,
      bytes32 salt,
      uint256[] memory extensions
    )
  {
    return (hex"0f", name, version, block.chainid, address(this), bytes32(0), new uint256[](0));
  }

  function _domainSeparatorV4() internal view returns (bytes32) {
    if (address(this) == CACHED_THIS && block.chainid == CACHED_CHAIN_ID) {
      return CACHED_DOMAIN_SEPARATOR;
    }

    return _buildDomainSeparator();
  }

  function _hashTypedDataV4(bytes32 _structHash) internal view virtual returns (bytes32) {
    return keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), _structHash));
  }

  function _buildDomainSeparator() private view returns (bytes32) {
    return keccak256(abi.encode(TYPE_HASH, HASHED_NAME, HASHED_VERSION, block.chainid, address(this)));
  }
}

